// Reads the scoresheet PDF ("Kampskema") served by api.volleyball.dk.
// The PDF is generated by iText with one standard font (Helvetica, WinAnsi) and every cell is drawn as
// `/F1 <size> Tf <x> <y> Td (<text>) Tj`, so a regex over the inflated content streams yields every text item with its
// position. No PDF library is needed. The layout is the FIVB scoresheet: five set boxes, then a player list.
// The result is plain, serializable data (no DOM, no Dates), so it can later be stored or aggregated across matches.

const ROMAN = ['I', 'II', 'III', 'IV', 'V', 'VI'];

/** PDF bytes (ArrayBuffer) -> [{ x, y, size, text }] with x/y at the start of the text's baseline. */
export async function pdfText(buffer) {
  const bytes = new Uint8Array(buffer);
  const bin = new TextDecoder('latin1').decode(bytes);
  if (!bin.startsWith('%PDF')) throw new Error('Not a PDF');
  const items = [];
  for (const m of bin.matchAll(/\/Filter\/FlateDecode\/Length (\d+)>>\s*stream\r?\n/g)) {
    const start = m.index + m[0].length;
    const stream = new Blob([bytes.subarray(start, start + +m[1])]).stream().pipeThrough(new DecompressionStream('deflate'));
    const src = new TextDecoder('latin1').decode(await new Response(stream).arrayBuffer());
    for (const [, size, x, y, body] of src.matchAll(/\/F\d+ ([\d.]+) Tf\s+([\d.-]+) ([\d.-]+) Td[^(]*?\(((?:\\.|[^\\)])*)\)Tj/g)) {
      const text = body.replace(/\\(\d{1,3}|.)/g, (_, c) => (/\d/.test(c) ? String.fromCharCode(parseInt(c, 8)) : c));
      items.push({ x: +x, y: +y, size: +size, text: text.replace(/\s+/g, ' ').trim() });
    }
  }
  return items;
}

// Helvetica widths in em, enough to find the centre of short numeric cells.
const centre = (t) => t.x + (t.size * [...t.text].reduce((w, c) => w + (/[\d]/.test(c) ? 0.556 : c === ':' ? 0.278 : 0.5), 0)) / 2;
const num = (t) => (/^\d{1,2}$/.test(t.text) ? +t.text : null);
const pair = (t) => t.text.match(/^(\d+):(\d+)$/)?.slice(1).map(Number) ?? null;
const time = (t) => t.text.match(/(\d{1,2}:\d{2})/)?.[1] ?? null;

/**
 * Text items -> {
 *   players: { [team name]: [{ no, name, libero }] },
 *   sets: [{ start: 'hh:mm', end, minutes,
 *            sides: [team serving first, the other], each { name, lineup: [6 shirt numbers in service order I-VI],
 *                   subs: [{ pos: 0-5, no, at: [own, opp], back: [own, opp] | null }],
 *                   rounds: [6 arrays: the team's own score each time that server lost the serve] } }]
 * }
 * Sets are in playing order; empty boxes are skipped (a best-of-3 decider is written in the set 5 box).
 */
export function parseScoresheet(items) {
  const at = (y, x0, x1, tol = 1.5) => items.filter((t) => Math.abs(t.y - y) <= tol && t.x >= x0 && t.x < x1);
  const labels = items.filter((t) => t.text === 'Service Order').sort((a, b) => b.y - a.y || a.x - b.x);

  const sets = [];
  for (const [i, label] of labels.entries()) {
    // A box runs from its label to the next label on the same row (or the page edge).
    const right = labels.find((l, j) => j > i && Math.abs(l.y - label.y) < 2)?.x ?? 842;
    const L = label.y;
    // Box header: "<team> Start: hh:mm S | <team> End: hh:mm R", the team serving first on the left.
    // A long team name wraps onto a second line, which pushes the rest of the box down.
    const startCell = items
      .filter((t) => t.text.startsWith('Start:') && t.x >= label.x && t.x < right && t.y > L + 5 && t.y < L + 35)
      .sort((a, b) => a.y - b.y)[0];
    if (!startCell) continue;
    const header = at(startCell.y, label.x, right);
    const endCell = header.find((t) => t.text.startsWith('End:'));
    const names = header
      .filter((t) => t !== startCell && t !== endCell && t.text !== 'Point at Change')
      .sort((a, b) => a.x - b.x)
      .slice(0, 2)
      .map((n) => [n, ...items.filter((t) => t.y < n.y - 2 && t.y > L + 3 && Math.abs(t.x - n.x) < 3)].map((t) => t.text).join(' '));

    const heads = at(L, label.x, right).filter((t) => ROMAN.includes(t.text)).sort((a, b) => a.x - b.x);
    const panels = [];
    for (let p = 0; p + 6 <= heads.length; p += 6) panels.push(heads.slice(p, p + 6).map(centre));
    const column = (cols, t) => cols.findIndex((x) => Math.abs(x - centre(t)) <= 9);
    const band = (cols, y0, y1) =>
      items.filter((t) => t.y < L - y0 && t.y >= L - y1 && t.x >= cols[0] - 15 && t.x < cols[5] + 10).map((t) => ({ t, k: column(cols, t) })).filter((c) => c.k >= 0);

    const read = (cols) => {
      const lineup = Array(6).fill(null);
      for (const { t, k } of band(cols, 6, 14)) lineup[k] = num(t);
      const subs = [];
      for (const { t, k } of band(cols, 16, 25)) if (num(t) !== null) subs.push({ pos: k, no: num(t), at: null, back: null });
      for (const { t, k } of band(cols, 26, 35)) { const s = subs.find((s) => s.pos === k); if (s && pair(t)) s.at = pair(t); }
      for (const { t, k } of band(cols, 36, 45)) { const s = subs.find((s) => s.pos === k); if (s && pair(t)) s.back = pair(t); }
      // Service rounds: rows about 9.5 pt apart; a cell holds the team's score when that server lost the serve.
      const rounds = Array.from({ length: 6 }, () => []);
      for (const { t, k } of band(cols, 46, 95)) if (num(t) !== null) rounds[k][Math.round((L - t.y - 50) / 9.5)] = num(t);
      return { lineup, subs, rounds };
    };

    const sides = panels.map(read);
    if (sides.length < 2 || sides[0].lineup.some((n) => n === null) || sides[1].lineup.some((n) => n === null)) continue;
    // Deciding set: the third panel continues the first team after the change of courts at 8 points.
    const after = sides[2];
    if (after) {
      for (let k = 0; k < 6; k++) after.rounds[k].forEach((v, r) => v !== undefined && (sides[0].rounds[k][r] ??= v));
      for (const s of after.subs) if (!sides[0].subs.some((o) => o.pos === s.pos && o.no === s.no)) sides[0].subs.push(s);
    }
    sets.push({
      names,
      start: time(startCell),
      end: endCell && time(endCell),
      sides: sides.slice(0, 2).map((s) => ({ ...s, rounds: s.rounds.map((r) => r.filter((v) => v !== undefined)) })),
    });
  }

  // Full team names from the title line ("<A> (A)  (B) <B>"); box headers may cut a name across two lines.
  const teams = items.filter((t) => t.size === 12 && t.x > 200 && t.y > (labels[0]?.y ?? 0)).sort((a, b) => a.x - b.x).map((t) => t.text);
  const resolve = (name) => teams.find((t) => t === name) ?? teams.find((t) => t.startsWith(name) || name.startsWith(t)) ?? name;

  // Result table: one "'<minutes>" cell per played set, then the total. It is computed from the clock times
  // the scorer entered, which are sometimes wrong (a 2-minute set), so implausibly short sets are dropped.
  const minutes = items.filter((t) => /^'\d+$/.test(t.text)).sort((a, b) => b.y - a.y).map((t) => +t.text.slice(1)).map((m) => (m >= 8 ? m : null));

  // Player lists: team A left, team B right; liberos follow the LIBERO heading.
  const listHead = items.filter((t) => t.text === 'Name of the player').sort((a, b) => a.x - b.x);
  const liberoY = items.find((t) => t.text === 'LIBERO')?.y ?? 0;
  const officialsY = items.find((t) => t.text === 'OFFICIALS')?.y ?? 0;
  const players = {};
  for (const [i, h] of listHead.entries()) {
    const right = listHead[i + 1] ? listHead[i + 1].x - 25 : 842;
    const list = (players[teams[i] ?? ''] = []);
    for (const n of items.filter((t) => t.y < h.y - 2 && t.y > officialsY && t.x > h.x - 20 && t.x < h.x - 5 && num(t) !== null)) {
      const name = at(n.y, h.x - 5, right, 1).find((t) => num(t) === null && t.text.length > 2);
      if (name) list.push({ no: num(n), name: name.text, libero: n.y < liberoY });
    }
  }

  return {
    players,
    sets: sets.map((s, i) => ({
      start: s.start,
      end: s.end,
      minutes: minutes[i] ?? null,
      sides: s.sides.map((side, j) => ({ name: resolve(s.names[j]), ...side })),
    })),
  };
}
